fn dispatch(cli: &Cli) -> Result<()> {
    if cli.context_basis.is_some()
        && !matches!(
            cli.command,
            Command::Intent(_)
                | Command::Project { .. }
                | Command::Author { .. }
                | Command::Migrate { .. }
                | Command::History { .. }
        )
    {
        anyhow::bail!("--context-basis requires a project, author or history transition command.");
    }
    if cli.save_plan
        && !matches!(
            &cli.command,
            Command::Author { .. }
                | Command::Migrate { .. }
                | Command::File { .. }
                | Command::Rename { .. }
                | Command::Extract { .. }
                | Command::Inline { .. }
                | Command::Signature { .. }
                | Command::Move { .. }
                | Command::Delete { .. }
                | Command::Imports { .. }
                | Command::Translate { .. }
                | Command::Recipe { .. }
                | Command::RemoveFlag { .. }
                | Command::Rewrite { .. }
                | Command::Restructure { .. }
                | Command::Spec {
                    command: SpecCommand::Init { .. }
                }
                | Command::Spec {
                    command: SpecCommand::Scaffold { .. }
                }
                | Command::Spec {
                    command: SpecCommand::Ci { .. }
                }
                | Command::Spec {
                    command: SpecCommand::Sync { .. }
                }
                | Command::Spec {
                    command: SpecCommand::Prove { .. }
                }
                | Command::Openapi { out: Some(_), .. }
        )
    {
        anyhow::bail!("--save-plan requires a command that produces a change plan.");
    }
    if cli.plan_basis.is_some()
        && !matches!(
            cli.command,
            Command::Author { .. } | Command::Migrate { .. }
        )
    {
        anyhow::bail!("--plan-basis requires an author or migration command.");
    }
    if !matches!(cli.command, Command::History { .. } | Command::Git { .. }) {
        if let Some(pending) = crate::history::History::read(&cli.root)?.pending {
            eprintln!(
                "Transaction {} needs recovery: fr history recover {} --write",
                pending.id, pending.id
            );
        }
    }
    match &cli.command {
        Command::Compatibility => cmd_compatibility(cli),
        Command::Checks(options) => {
            let report = crate::checks::report(&workspace_root(cli), options)?;
            println!("{}", serde_json::to_string(&report)?);
            if report["passed"] == false {
                std::process::exit(1);
            }
            Ok(())
        }
        Command::Author { command } => cmd_author(cli, command),
        Command::File { command } => {
            let report = crate::history::files::execute(&cli.root, command, cli.save_plan)?;
            println!("{}", serde_json::to_string(&report)?);
            Ok(())
        }
        Command::Git { command } => {
            println!(
                "{}",
                serde_json::to_string(&crate::git::report(&cli.root, command)?)?
            );
            Ok(())
        }
        Command::Audit(options) => cmd_audit(cli, options),
        Command::Intent(options) => cmd_intent(cli, options),
        Command::Guide(options) => with_project(cli, |project, root| {
            let report = project.agent_guide(options)?;
            project.verify(root)?;
            println!("{}", serde_json::to_string(&report)?);
            Ok(())
        }),
        Command::Project { command } => cmd_project(cli, command),
        Command::TaskChange(options) => cmd_task_change(cli, options),
        Command::Workflow(options) => {
            let outcome = crate::workflow::run(&workspace_root(cli), options)?;
            println!("{}", serde_json::to_string(&outcome.report)?);
            if !outcome.passed {
                std::process::exit(1);
            }
            Ok(())
        }
        Command::Migrate { command } => cmd_migrate(cli, command),
        Command::History { action } => cmd_history(cli, action.as_ref()),
        Command::Capabilities {
            capability,
            language,
            markdown,
        } => cmd_capabilities(cli, capability.as_deref(), language.as_deref(), *markdown),
        Command::Completions { shell } => {
            print!("{}", completion_script(*shell));
            Ok(())
        }
        Command::Cache { clear } => cmd_cache(cli, *clear),
        Command::Scan { languages } => cmd_scan(cli, languages),
        Command::Parse { languages, stats } => cmd_parse(cli, languages, *stats),
        Command::Symbols {
            languages,
            name,
            kind,
            stats,
            paths,
        } => cmd_symbols(
            cli,
            languages,
            name.as_deref(),
            kind.as_deref(),
            *stats,
            paths,
        ),
        Command::Def { target, first } => cmd_def(cli, target, *first),
        Command::Type { target } => cmd_type(cli, target),
        Command::Implementations { target } => cmd_implementations(cli, target),
        Command::Usages {
            target,
            include_unresolved,
        } => cmd_usages(cli, target, *include_unresolved),
        Command::Refs {
            target,
            include_unresolved,
        } => cmd_refs(cli, target, *include_unresolved),
        Command::Rename {
            target,
            new_name,
            write,
        } => cmd_rename(cli, target, new_name, *write),
        Command::Callers { target, depth } => cmd_trace(cli, target, *depth, Direction2::Callers),
        Command::Callees { target, depth } => cmd_trace(cli, target, *depth, Direction2::Callees),
        Command::Flow {
            direction,
            target,
            depth,
            values,
            set,
            set_string,
            set_file,
            set_json,
        } => {
            let inputs = crate::analysis::provenance::ValuesInputs::parse(
                values,
                crate::analysis::provenance::SetFlags {
                    sets: set,
                    strings: set_string,
                    files: set_file,
                    jsons: set_json,
                },
            )?;
            cmd_flow(cli, direction, target, *depth, &inputs)
        }
        Command::Extract {
            range,
            name,
            function,
            all,
            write,
        } => cmd_extract(
            cli,
            range,
            name,
            match *function {
                true => Extract::Function,
                false => Extract::Variable,
            },
            match *all {
                true => Occurrences::All,
                false => Occurrences::First,
            },
            *write,
        ),
        Command::Inline {
            target,
            call,
            write,
        } => cmd_inline(
            cli,
            target,
            match *call {
                true => Inline::Call,
                false => Inline::Variable,
            },
            *write,
        ),
        Command::Openapi { out, yaml } => cmd_openapi(cli, out.as_deref(), *yaml),
        Command::Recipe {
            command,
            file,
            write,
            explain,
            catalogs,
            vocabulary,
        } => match command {
            Some(RecipeCommand::Fmt {
                paths,
                write,
                check,
            }) => cmd_recipe_fmt(cli, paths, *write, *check),
            None => cmd_recipe(
                cli,
                file.as_deref(),
                *write,
                *explain,
                catalogs,
                *vocabulary,
            ),
        },
        Command::Spec { command } => match command {
            SpecCommand::Kernel { from, report_bytes } => cmd_spec_kernel(cli, from, *report_bytes),
            SpecCommand::Candidates { paths, limit } => cmd_spec_candidates(cli, paths, *limit),
            SpecCommand::Plan {
                target,
                properties,
                property_files,
            } => cmd_spec_plan(cli, target, properties, property_files),
            SpecCommand::PropertyTask {
                target,
                token_limit,
            } => cmd_spec_property_task(cli, target, *token_limit),
            SpecCommand::Init { path, write } => cmd_spec_init(cli, path, *write),
            SpecCommand::Scaffold {
                target,
                from,
                package,
                write,
            } => match (target.as_deref(), from.as_deref()) {
                (Some(target), None) => cmd_spec_scaffold(cli, target, package, *write),
                (None, Some(plan)) => cmd_spec_scaffold_formal(cli, plan, package, *write),
                _ => anyhow::bail!("spec scaffold requires either TARGET or --from PLAN."),
            },
            SpecCommand::Goals {
                paths,
                goal,
                limit,
                token_limit,
            } => cmd_spec_goals(cli, paths, goal.as_deref(), *limit, *token_limit),
            SpecCommand::ProofTask {
                target,
                token_limit,
            } => cmd_spec_proof_task(cli, target, *token_limit),
            SpecCommand::ProofCheck {
                target,
                from,
                token_limit,
            } => cmd_spec_proof_check(cli, target, from, *token_limit),
            SpecCommand::Prove {
                target,
                from,
                write,
            } => cmd_spec_prove(cli, target, from, *write),
            SpecCommand::Ci {
                package,
                max_debt,
                write,
            } => cmd_spec_ci(cli, package, *max_debt, *write),
            SpecCommand::Snapshot { target } => {
                let report = crate::spec::refinement::capture(&workspace_root(cli), target)?;
                println!("{}", serde_json::to_string_pretty(&report)?);
                Ok(())
            }
            SpecCommand::Compare { from, package, basis, write } => {
                cmd_spec_compare(cli, from, package, basis.as_deref(), *write)
            }
            SpecCommand::Retain(options) => {
                let report = crate::spec::retained::report(&workspace_root(cli), options)?;
                println!("{}", serde_json::to_string_pretty(&report)?);
                if report["executed"] == true && report["passed"] != true {
                    std::process::exit(1);
                }
                Ok(())
            }
            SpecCommand::Evidence { paths } => cmd_spec_evidence(cli, paths),
            SpecCommand::Check {
                paths,
                strict,
                max_debt,
            } => cmd_spec_check(cli, paths, *strict, *max_debt),
            SpecCommand::Sync { paths, write } => cmd_spec_sync(cli, paths, *write),
            SpecCommand::Verify { paths } => cmd_spec_verify(cli, paths),
        },
        Command::RemoveFlag { flag, value, write } => {
            cmd_remove_flag(cli, flag, FlagValue(*value), *write)
        }
        Command::Rewrite {
            target,
            rewrite,
            write,
        } => cmd_rewrite(cli, target, rewrite.as_deref(), *write),
        Command::Restructure {
            pattern,
            template,
            language,
            write,
        } => cmd_restructure(cli, pattern, template, language, *write),
        Command::Delete { target, write } => cmd_delete(cli, target, *write),
        Command::Duplicates {
            min_tokens,
            exact,
            languages,
            paths,
        } => cmd_duplicates(cli, *min_tokens, *exact, languages, paths),
        Command::Unused {
            catalogs,
            languages,
            paths,
            internal,
        } => cmd_unused(cli, catalogs.as_deref(), languages, paths, *internal),
        Command::Imports { file, write } => cmd_imports(cli, file.as_deref(), *write),
        Command::Translate {
            file,
            language,
            write,
            out,
            force,
        } => cmd_translate(
            cli,
            file,
            language.as_deref(),
            *write,
            out.as_deref(),
            *force,
        ),
        Command::Move {
            target,
            destination,
            write,
        } => cmd_move(cli, target, destination, *write),
        Command::Signature {
            target,
            change,
            write,
        } => cmd_signature(cli, target, change, *write),
        Command::Stitch {
            env,
            orphaned,
            files,
            flags,
        } => cmd_stitch(cli, env.as_deref(), *orphaned, *files, *flags),
        Command::Impact {
            target,
            caller_depth,
        } => cmd_impact(cli, target, *caller_depth),
        Command::Graph { dot } => cmd_graph(cli, *dot),
        Command::Entrypoints {
            kind,
            catalogs,
            unreachable,
        } => cmd_entrypoints(cli, kind.as_deref(), catalogs.as_deref(), *unreachable),
    }
}
